-- db/extras/lugares_import/lugares_02.sql
-- GERADO por scripts/lugares-para-servicos.mjs — não edite à mão; rode o script de novo.
-- De-para: docs/integracoes/lugares-depara.md
--
-- Grava artigos de content/lugares/ como anúncios (public.services) no tenant do usuário root:
-- goiabeiras-shopping, lua-morena, musiva-cuiaba — 2 foto(s). Status no INSERT: 'pending' (o dono aprova no painel).
-- Idempotente: o anúncio é achado por extras.origem (fonte = 'content/lugares', slug); rodar de novo
-- atualiza, não duplica. Fotos têm id determinístico pelo conteúdo (sha256).
-- Uma transação por arquivo: qualquer erro desfaz o arquivo inteiro. Os arquivos são independentes.
--
-- Pré-requisitos: core + plugins instalados, root cadastrado, grupo "lugares" na taxonomia
-- (db/extras/taxonomy_seed_bora_cuiaba.sql ou, em banco com anúncios, db/extras/lugares_grupo_migracao.sql),
-- formulário db/extras/forms_seed_lugares.sql e, para o código IBGE, db/extras/location_seed_bora_cuiaba.sql.
-- Atenção: depois deste import existem serviços, e o seed de taxonomia (destrutivo) passa a abortar.
--
-- Aplicar:
--   node kizuna-core/cli db run db/extras/lugares_import/lugares_02.sql          (usa $DATABASE_URL; ou --db-url <url>)
--   psql "$DATABASE_URL" -v ON_ERROR_STOP=1 -f db/extras/lugares_import/lugares_02.sql

BEGIN;

-- Goiabeiras Shopping (content/lugares/goiabeiras-shopping/index.md) — 2 foto(s)
DO $lugar_1$
DECLARE
  c_slug      constant text   := 'goiabeiras-shopping';
  c_extras    constant jsonb  := '{"origem":{"fonte":"content/lugares","slug":"goiabeiras-shopping","arquivo":"content/lugares/goiabeiras-shopping/index.md","atualizado_em":"2026-10-11","status_artigo":"revisao","categoria_artigo":"Shopping","cidade":"cuiaba-mt","titulo_md5":"dc27ddcff82654aef4b73323af829d7c","descricao_md5":"dda52dc3168de430134d2fb033b0f7e4","fotos":[{"arquivo":"public/lugares/goiabeiras-shopping/01.jpg","sha256":"7f13732e2eb1fe8c0f6a19af563dddcd602861d15a190dfe14bb86e4a9bcc970","fileId":"65e8b975-983a-55ef-b743-4fe29271e2ff"},{"arquivo":"public/lugares/goiabeiras-shopping/02.jpg","sha256":"cccd1bb5cdba70bf73537cb3f6f0f1bd686403a4ce6c1f15662aa56396f29e5e","fileId":"a5869fa9-7294-5514-a70c-2f70ec09995c"}]},"resumo":"Shopping inaugurado em 1989 na Av. José Monteiro de Figueiredo, em Cuiabá, com lojas, praça de alimentação e o cinema Cinelaser Goiabeiras.","endereco_texto":"Av. José Monteiro de Figueiredo, 500, Duque de Caxias, Cuiabá - MT","horario":[{"texto":"Lojas: seg a sáb, 10h às 22h; dom, 14h às 20h"},{"texto":"Praça de alimentação e restaurantes: todos os dias, 11h às 22h"},{"texto":"Cinema: conforme a programação"}],"dicas_chegada":"O shopping tem estacionamento, listado entre os serviços no site oficial, que não detalha regras nem valores. Outros serviços: bicicletário, fraldário e caixa eletrônico.","contato_telefone":"(65) 3315-2300","contato_instagram":"@goiabeirasshopping","site":"https://www.goiabeirasshopping.com.br","creditos":"Fotos: Mateus Hidalgo, licença CC BY-SA 2.0, via Flickr (imagens de 2012; lojas e decoração podem ter mudado).","tags":["shoppings","local:goiabeiras-shopping"],"codigo":"goiabeiras-shopping"}'::jsonb;
  c_titulo    constant text   := 'Goiabeiras Shopping';
  c_descricao constant text   := 'O Goiabeiras Shopping fica na Avenida José Monteiro de Figueiredo, 500, no bairro Duque de Caxias, em Cuiabá. Inaugurado em 1989, reúne lojas, restaurantes, serviços e um cinema, o Cinelaser Goiabeiras. Segundo o site oficial, as lojas abrem de segunda a sábado, das 10h às 22h, e aos domingos, das 14h às 20h.

## Um shopping de 1989

O shopping foi inaugurado em 27 de junho de 1989, conforme reportagem do Diário de Cuiabá de 2005, que marcou os 16 anos do empreendimento. O site oficial o descreve como o primeiro shopping do estado de Mato Grosso.

A imprensa local faz uma ressalva. O restaurador Jefferson Silveira, ouvido pelo Olhar Direto, lembra que o Shopping Tabor, na Voluntários da Pátria, foi o primeiro da capital, e que o Goiabeiras foi o primeiro grande shopping no modelo que se conhece hoje. Segundo a mesma reportagem, a inauguração teve shows de Sandra de Sá e da Banda Terra.

## Estrutura

De acordo com a ficha publicada pela administradora, a Soul Malls, o shopping tem 26 mil metros quadrados de área bruta locável, cinco pisos, sete âncoras e megalojas e 1.100 vagas de estacionamento.

O site oficial organiza as lojas em categorias como vestuário, calçados, óticas e perfumaria. Há também operações de serviços, entre elas academia, barbearia, casa de câmbio, clínica médica, coworking, faculdade, lavanderia e salão de beleza.

Em 2025, segundo a Abrasce e o portal RDNews, o shopping inaugurou mais de dez operações, entre elas Sebrae/MT, Life By Vivara, Baby & Mom, Via Mia, Gracie One e Fare Joias.

## Alimentação

A praça de alimentação e os restaurantes funcionam todos os dias, das 11h às 22h, conforme o site oficial. Entre as operações listadas estão Burger King, McDonald''s, Cacau Show, Kopenhagen, Café e Prosa, Renata''s Restaurante, Serra Restaurante e Tapiocaria Pantanal.

## Cinema

O Cinelaser Goiabeiras reabriu o cinema do shopping em 20 de março de 2025, segundo o MidiaNews e a Gazeta Digital. As salas estavam fechadas desde julho de 2024, quando a Cinemark deixou Cuiabá. A inauguração oficial foi em 10 de abril, de acordo com o RDNews.

O complexo tem cinco salas, com projeção a laser, poltronas VIP e Premium e a sala Maxlaser, que usa som Dolby Atmos e projeção em 4K, segundo material da rede publicado pela Abrasce. A programação semanal está no site oficial do shopping.

## Serviços

Entre os serviços listados no site oficial estão estacionamento, bicicletário, fraldário, banheiro família, carrinho de bebê, carrinho para pet, cadeira de rodas, caixa eletrônico e as tags Veloe e Sem Parar.

Para dúvidas sobre horários especiais, estacionamento ou lojas, o atendimento ao cliente responde pelo telefone (65) 3315-2300 e pelo e-mail sac.goiabeiras@soulmalls.com.br.

Fotos: Mateus Hidalgo, licença CC BY-SA 2.0, via Flickr (imagens de 2012; lojas e decoração podem ter mudado).';
  c_images    constant text[] := ARRAY['65e8b975-983a-55ef-b743-4fe29271e2ff', 'a5869fa9-7294-5514-a70c-2f70ec09995c']::text[];
  c_subs      constant text[] := ARRAY['shoppings']::text[];
  c_answers   constant jsonb  := '{"horario":[{"texto":"Lojas: seg a sáb, 10h às 22h; dom, 14h às 20h"},{"texto":"Praça de alimentação e restaurantes: todos os dias, 11h às 22h"},{"texto":"Cinema: conforme a programação"}],"dicas_chegada":"O shopping tem estacionamento, listado entre os serviços no site oficial, que não detalha regras nem valores. Outros serviços: bicicletário, fraldário e caixa eletrônico.","contato_telefone":"(65) 3315-2300","contato_instagram":"@goiabeirasshopping","site":"https://www.goiabeirasshopping.com.br"}'::jsonb;
  c_form_keys constant text[] := ARRAY['horario', 'preco', 'gratuito', 'dicas_chegada', 'contato_telefone', 'contato_whatsapp', 'contato_instagram', 'site']::text[];
  v_root uuid; v_tenant uuid; v_group bigint; v_cat bigint; v_form text; v_form_id bigint; v_form_ver int; v_form_schema jsonb;
  v_sid bigint; v_old jsonb; v_old_titulo text; v_old_desc text;
  v_old_import text[]; v_kept text[]; v_images jsonb; v_cover text; v_ibge text; v_missing text[];
BEGIN
  SELECT u.uid, t.uid INTO v_root, v_tenant
  FROM (SELECT uid FROM auth.users WHERE is_root = true ORDER BY created_at LIMIT 1) u
  JOIN LATERAL (SELECT tn.uid FROM auth.tenants tn WHERE tn.owner_uid = u.uid ORDER BY tn.created_at LIMIT 1) t ON true;
  IF v_tenant IS NULL THEN RAISE EXCEPTION 'lugares: sem usuário root/tenant'; END IF;

  SELECT g.id, c.id, NULLIF(c.form_key, '') INTO v_group, v_cat, v_form
  FROM public.categories c JOIN public.categories_group g ON g.id = c.category_group_id
  WHERE g.slug = 'lugares' AND c.slug = 'compras';
  IF v_cat IS NULL THEN RAISE EXCEPTION 'lugares/%: categoria lugares/compras não existe (rode o seed de taxonomia)', c_slug; END IF;
  IF v_form IS NULL THEN
    RAISE NOTICE 'lugares/%: a categoria não tem form_key (rode db/extras/forms_seed_lugares.sql); horário/contato só em services.extras', c_slug;
  ELSE
    SELECT id, version, schema INTO v_form_id, v_form_ver, v_form_schema
    FROM public.forms WHERE tenant_id = v_tenant AND form_key = v_form AND active;
    IF v_form_id IS NULL THEN RAISE EXCEPTION 'lugares/%: formulário % não existe no tenant', c_slug, v_form; END IF;
  END IF;

  SELECT array_agg(s) INTO v_missing FROM unnest(c_subs) s
  WHERE NOT EXISTS (SELECT 1 FROM public.categories_sub cs WHERE cs.slug = s AND cs.category_id = v_cat);
  IF v_missing IS NOT NULL THEN RAISE EXCEPTION 'lugares/%: subcategoria(s) % não existem sob compras', c_slug, v_missing; END IF;

  -- Fotos (id determinístico pelo conteúdo: rodar de novo não duplica)
  INSERT INTO public.files (id, uid, tenant_id, original_name, storage_path, mime_type, size_bytes, width, height, purpose, content, active)
  VALUES ('65e8b975-983a-55ef-b743-4fe29271e2ff', v_root, v_tenant, 'goiabeiras-shopping-01.jpg', 'service_image/2026/10/65e8b975-983a-55ef-b743-4fe29271e2ff-goiabeiras-shopping-01.jpg', 'image/jpeg', 174628, 1024, 679, 'service_image',
          decode('', 'hex'), true)
  ON CONFLICT (id) DO UPDATE SET active = true, updated_at = now();
  INSERT INTO public.files (id, uid, tenant_id, original_name, storage_path, mime_type, size_bytes, width, height, purpose, content, active)
  VALUES ('a5869fa9-7294-5514-a70c-2f70ec09995c', v_root, v_tenant, 'goiabeiras-shopping-02.jpg', 'service_image/2026/10/a5869fa9-7294-5514-a70c-2f70ec09995c-goiabeiras-shopping-02.jpg', 'image/jpeg', 215824, 1024, 679, 'service_image',
          decode('', 'hex'), true)
  ON CONFLICT (id) DO UPDATE SET active = true, updated_at = now();

  -- Serviço existente? (chave: extras.origem.fonte + slug; inclui inativo, que não é reativado)
  SELECT id, extras, title, description INTO v_sid, v_old, v_old_titulo, v_old_desc
  FROM public.services
  WHERE tenant_id = v_tenant AND extras->'origem'->>'fonte' = 'content/lugares' AND extras->'origem'->>'slug' = c_slug
  ORDER BY id LIMIT 1;

  -- Imagens: as do artigo primeiro; as que alguém subiu pelo painel continuam depois
  SELECT coalesce(array_agg(x), '{}') INTO v_old_import
  FROM (SELECT f->>'fileId' AS x FROM jsonb_array_elements(coalesce(v_old->'origem'->'fotos', '[]'::jsonb)) f) y;
  SELECT coalesce(array_agg(x ORDER BY o), '{}') INTO v_kept
  FROM jsonb_array_elements_text(coalesce(v_old->'images', '[]'::jsonb)) WITH ORDINALITY AS a(x, o)
  WHERE x <> ALL(v_old_import) AND x <> ALL(c_images);
  v_images := to_jsonb(c_images || v_kept);
  v_cover := CASE
    WHEN v_old->>'coverFileId' IS NOT NULL AND v_old->>'coverFileId' <> ALL(v_old_import)
         AND (c_images || v_kept) @> ARRAY[v_old->>'coverFileId'] THEN v_old->>'coverFileId'
    ELSE (c_images || v_kept)[1] END;

  -- Foto que saiu do artigo: desativa o arquivo antigo
  UPDATE public.files SET active = false, updated_at = now()
  WHERE id::text = ANY(v_old_import) AND id::text <> ALL(c_images) AND active;

  IF v_sid IS NULL THEN
    INSERT INTO public.services
      (title, category_group_id, category_id, description, starting_price, price_unit, status,
       service_location, extras, tenant_id, created_by, active)
    VALUES (c_titulo, v_group, v_cat, c_descricao, 0, 'quote', 'pending'::public.service_status,
            'no_estabelecimento',
            c_extras || jsonb_strip_nulls(jsonb_build_object('images', CASE WHEN jsonb_array_length(v_images) > 0 THEN v_images END, 'coverFileId', v_cover)),
            v_tenant, v_root, true)
    RETURNING id INTO v_sid;
    RAISE NOTICE 'lugares/%: inserido (service id %)', c_slug, v_sid;
  ELSE
    -- Título/descrição só mudam se ninguém os editou desde o último import (md5 guardado em extras.origem)
    UPDATE public.services SET
      title = CASE WHEN v_old->'origem'->>'titulo_md5' IS NULL OR md5(v_old_titulo) = v_old->'origem'->>'titulo_md5'
                   THEN c_titulo ELSE title END,
      description = CASE WHEN v_old->'origem'->>'descricao_md5' IS NULL OR md5(coalesce(v_old_desc, '')) = v_old->'origem'->>'descricao_md5'
                         THEN c_descricao ELSE description END,
      category_group_id = v_group, category_id = v_cat,
      extras = (extras - 'origem' - 'resumo' - 'endereco_texto' - 'contato' - c_form_keys
                       - 'creditos' - 'tags' - 'codigo' - 'vinculosTitulo' - 'images' - 'coverFileId')
               || jsonb_set(c_extras, '{origem}', (c_extras->'origem')
                    || jsonb_build_object(
                         'titulo_md5', CASE WHEN v_old->'origem'->>'titulo_md5' IS NULL OR md5(v_old_titulo) = v_old->'origem'->>'titulo_md5'
                                            THEN c_extras->'origem'->>'titulo_md5' ELSE v_old->'origem'->>'titulo_md5' END,
                         'descricao_md5', CASE WHEN v_old->'origem'->>'descricao_md5' IS NULL OR md5(coalesce(v_old_desc, '')) = v_old->'origem'->>'descricao_md5'
                                               THEN c_extras->'origem'->>'descricao_md5' ELSE v_old->'origem'->>'descricao_md5' END))
               || jsonb_strip_nulls(jsonb_build_object('images', CASE WHEN jsonb_array_length(v_images) > 0 THEN v_images END, 'coverFileId', v_cover)),
      updated_at = now()
    WHERE id = v_sid;
    RAISE NOTICE 'lugares/%: atualizado (service id %)', c_slug, v_sid;
  END IF;

  -- Endereço (apaga os do anúncio e grava um, principal)
  DELETE FROM public.service_addresses WHERE service_id = v_sid;
  BEGIN
    SELECT lc.id::text INTO v_ibge FROM public.location_city lc JOIN public.location_state ls ON ls.id = lc.state_id
    WHERE lower(lc.name) = lower('Cuiabá') AND upper(ls.code) = 'MT' LIMIT 1;
  EXCEPTION WHEN undefined_table THEN v_ibge := NULL;
  END;
  IF v_ibge IS NULL THEN RAISE NOTICE 'lugares/%: cidade % / % sem código IBGE em location_city', c_slug, 'Cuiabá', 'MT'; END IF;
  INSERT INTO public.service_addresses
    (service_id, label, street, number, complement, neighborhood, city, state, city_ibge,
     latitude, longitude, is_primary, tenant_id, created_by, active)
  VALUES (v_sid, c_titulo, 'Av. José Monteiro de Figueiredo', '500', NULL, 'Duque de Caxias', 'Cuiabá', 'MT', v_ibge,
          -15.5882, -56.1124, true, v_tenant, v_root, true);

  -- Respostas do formulário (mesmas chaves de extras)
  IF v_form_id IS NOT NULL THEN
    INSERT INTO public.form_results
      (form_id, form_key, reference_id, domain, version, schema_snapshot, answers, submitted_by, tenant_id)
    VALUES (v_form_id, v_form, v_sid::text, 'service', v_form_ver, v_form_schema, c_answers, v_root, v_tenant)
    ON CONFLICT (tenant_id, domain, reference_id) DO UPDATE SET
      answers = EXCLUDED.answers, version = EXCLUDED.version, schema_snapshot = EXCLUDED.schema_snapshot,
      form_id = EXCLUDED.form_id, form_key = EXCLUDED.form_key, updated_at = now();
  END IF;

  -- Subcategorias
  DELETE FROM public.service_categories_sub scs USING public.categories_sub cs
  WHERE scs.service_id = v_sid AND cs.id = scs.category_sub_id
    AND (cs.category_id <> v_cat OR cs.slug <> ALL(c_subs));
  INSERT INTO public.service_categories_sub (service_id, category_group_id, category_id, category_sub_id, tenant_id, created_by)
  SELECT v_sid, v_group, v_cat, cs.id, v_tenant, v_root
  FROM public.categories_sub cs WHERE cs.category_id = v_cat AND cs.slug = ANY(c_subs)
  ON CONFLICT (service_id, category_sub_id) DO NOTHING;
END
$lugar_1$;

-- Lua Morena (content/lugares/lua-morena/index.md) — 0 foto(s)
DO $lugar_2$
DECLARE
  c_slug      constant text   := 'lua-morena';
  c_extras    constant jsonb  := '{"origem":{"fonte":"content/lugares","slug":"lua-morena","arquivo":"content/lugares/lua-morena/index.md","atualizado_em":"2026-10-11","status_artigo":"rascunho","categoria_artigo":"Casa noturna","cidade":"cuiaba-mt","titulo_md5":"3b49f89f1449448aafed3efd39d3b32f","descricao_md5":"0f1b9b6c4974ec69be6208acbf212387"},"resumo":"Casa noturna de Cuiabá na Av. Jornalista Arquimedes Pereira Lima, com bailes, shows e festas de forró, sertanejo, brega e flashback.","endereco_texto":"Avenida Jornalista Arquimedes Pereira Lima, Cuiabá - MT","contato_telefone":"(65) 99946-6305","contato_instagram":"@luamorenacuiaba","tags":["casas-noturnas","local:lua-morena"],"codigo":"lua-morena"}'::jsonb;
  c_titulo    constant text   := 'Lua Morena';
  c_descricao constant text   := 'O Lua Morena é uma casa noturna de Cuiabá, na Avenida Jornalista Arquimedes Pereira Lima. Recebe bailes, shows e festas dançantes, com programação que passa por forró, sertanejo, brega e noites de flashback, segundo a imprensa local e os guias de eventos da cidade.

## O que é a casa

A imprensa cuiabana a descreve como uma "tradicional casa noturna da cidade", nas palavras do portal HiperNotícias, em 2024. O Veja Bem MT, em fevereiro de 2026, explicou que o nome vem da beleza do luar do cerrado e da cor morena da terra e da cultura local, e que a ideia era criar um espaço acolhedor para o forró, o sertanejo e os ritmos regionais.

A casa comemora aniversário em fevereiro. Em 2024, a festa foi na sexta-feira, 23 de fevereiro, às 21h, com a Banda Novo Som, Léo Vaqueiro e DJs na programação. Em 2026, o Veja Bem MT noticiou que a casa completava 25 anos, com show da banda Liga Joe no sábado, 7 de fevereiro.

## Programação

A agenda varia de uma edição para outra e mistura atrações nacionais, bandas locais, DJs e festas temáticas. Alguns registros recentes:

- **Novembro de 2024:** o grupo Double You, sucesso dos anos 1990, tocou na casa. Segundo o HiperNotícias, a noite de quinta-feira, 14, esgotou, e uma segunda apresentação foi marcada para sexta-feira, 15.
- **Junho de 2025:** festa Flashback no sábado, 7, às 21h. O Olhar Direto informou ingressos a partir de R$ 40.
- **Fevereiro de 2026:** show de aniversário com Liga Joe, em 7 de fevereiro.
- **Outubro de 2026:** o site Waltinho Eventos anuncia um show na casa em 17 de outubro, às 21h.

Nos eventos acima que tiveram horário divulgado, a noite começa às 21h. Valores e horários mudam por edição.

## Ingressos e estrutura

Para o show do Double You, em 2024, o HiperNotícias listou ingressos de pista e opções de mesas, camarotes e bistrôs, vendidos pela Casa de Festas, pela Prime Eventos Cuiabá, pela Moda Verão Esporte e por um site de ingressos. A mesma reportagem trata a casa como parceira da Waltinho Produções na organização do show. O perfil do Lua Morena no Instagram aponta para o site da Waltinho Eventos.

## Contato

O telefone divulgado pela casa e por guias de eventos é (65) 99946-6305. O perfil no Instagram, @luamorenacuiaba, é onde a programação é anunciada. Como datas, atrações e preços mudam, vale conferir ali antes de ir.';
  c_images    constant text[] := ARRAY[]::text[];
  c_subs      constant text[] := ARRAY['casas-noturnas']::text[];
  c_answers   constant jsonb  := '{"contato_telefone":"(65) 99946-6305","contato_instagram":"@luamorenacuiaba"}'::jsonb;
  c_form_keys constant text[] := ARRAY['horario', 'preco', 'gratuito', 'dicas_chegada', 'contato_telefone', 'contato_whatsapp', 'contato_instagram', 'site']::text[];
  v_root uuid; v_tenant uuid; v_group bigint; v_cat bigint; v_form text; v_form_id bigint; v_form_ver int; v_form_schema jsonb;
  v_sid bigint; v_old jsonb; v_old_titulo text; v_old_desc text;
  v_old_import text[]; v_kept text[]; v_images jsonb; v_cover text; v_ibge text; v_missing text[];
BEGIN
  SELECT u.uid, t.uid INTO v_root, v_tenant
  FROM (SELECT uid FROM auth.users WHERE is_root = true ORDER BY created_at LIMIT 1) u
  JOIN LATERAL (SELECT tn.uid FROM auth.tenants tn WHERE tn.owner_uid = u.uid ORDER BY tn.created_at LIMIT 1) t ON true;
  IF v_tenant IS NULL THEN RAISE EXCEPTION 'lugares: sem usuário root/tenant'; END IF;

  SELECT g.id, c.id, NULLIF(c.form_key, '') INTO v_group, v_cat, v_form
  FROM public.categories c JOIN public.categories_group g ON g.id = c.category_group_id
  WHERE g.slug = 'lugares' AND c.slug = 'vida-noturna';
  IF v_cat IS NULL THEN RAISE EXCEPTION 'lugares/%: categoria lugares/vida-noturna não existe (rode o seed de taxonomia)', c_slug; END IF;
  IF v_form IS NULL THEN
    RAISE NOTICE 'lugares/%: a categoria não tem form_key (rode db/extras/forms_seed_lugares.sql); horário/contato só em services.extras', c_slug;
  ELSE
    SELECT id, version, schema INTO v_form_id, v_form_ver, v_form_schema
    FROM public.forms WHERE tenant_id = v_tenant AND form_key = v_form AND active;
    IF v_form_id IS NULL THEN RAISE EXCEPTION 'lugares/%: formulário % não existe no tenant', c_slug, v_form; END IF;
  END IF;

  SELECT array_agg(s) INTO v_missing FROM unnest(c_subs) s
  WHERE NOT EXISTS (SELECT 1 FROM public.categories_sub cs WHERE cs.slug = s AND cs.category_id = v_cat);
  IF v_missing IS NOT NULL THEN RAISE EXCEPTION 'lugares/%: subcategoria(s) % não existem sob vida-noturna', c_slug, v_missing; END IF;

  -- Fotos (id determinístico pelo conteúdo: rodar de novo não duplica)
  -- (sem fotos)

  -- Serviço existente? (chave: extras.origem.fonte + slug; inclui inativo, que não é reativado)
  SELECT id, extras, title, description INTO v_sid, v_old, v_old_titulo, v_old_desc
  FROM public.services
  WHERE tenant_id = v_tenant AND extras->'origem'->>'fonte' = 'content/lugares' AND extras->'origem'->>'slug' = c_slug
  ORDER BY id LIMIT 1;

  -- Imagens: as do artigo primeiro; as que alguém subiu pelo painel continuam depois
  SELECT coalesce(array_agg(x), '{}') INTO v_old_import
  FROM (SELECT f->>'fileId' AS x FROM jsonb_array_elements(coalesce(v_old->'origem'->'fotos', '[]'::jsonb)) f) y;
  SELECT coalesce(array_agg(x ORDER BY o), '{}') INTO v_kept
  FROM jsonb_array_elements_text(coalesce(v_old->'images', '[]'::jsonb)) WITH ORDINALITY AS a(x, o)
  WHERE x <> ALL(v_old_import) AND x <> ALL(c_images);
  v_images := to_jsonb(c_images || v_kept);
  v_cover := CASE
    WHEN v_old->>'coverFileId' IS NOT NULL AND v_old->>'coverFileId' <> ALL(v_old_import)
         AND (c_images || v_kept) @> ARRAY[v_old->>'coverFileId'] THEN v_old->>'coverFileId'
    ELSE (c_images || v_kept)[1] END;

  -- Foto que saiu do artigo: desativa o arquivo antigo
  UPDATE public.files SET active = false, updated_at = now()
  WHERE id::text = ANY(v_old_import) AND id::text <> ALL(c_images) AND active;

  IF v_sid IS NULL THEN
    INSERT INTO public.services
      (title, category_group_id, category_id, description, starting_price, price_unit, status,
       service_location, extras, tenant_id, created_by, active)
    VALUES (c_titulo, v_group, v_cat, c_descricao, 0, 'quote', 'pending'::public.service_status,
            'no_estabelecimento',
            c_extras || jsonb_strip_nulls(jsonb_build_object('images', CASE WHEN jsonb_array_length(v_images) > 0 THEN v_images END, 'coverFileId', v_cover)),
            v_tenant, v_root, true)
    RETURNING id INTO v_sid;
    RAISE NOTICE 'lugares/%: inserido (service id %)', c_slug, v_sid;
  ELSE
    -- Título/descrição só mudam se ninguém os editou desde o último import (md5 guardado em extras.origem)
    UPDATE public.services SET
      title = CASE WHEN v_old->'origem'->>'titulo_md5' IS NULL OR md5(v_old_titulo) = v_old->'origem'->>'titulo_md5'
                   THEN c_titulo ELSE title END,
      description = CASE WHEN v_old->'origem'->>'descricao_md5' IS NULL OR md5(coalesce(v_old_desc, '')) = v_old->'origem'->>'descricao_md5'
                         THEN c_descricao ELSE description END,
      category_group_id = v_group, category_id = v_cat,
      extras = (extras - 'origem' - 'resumo' - 'endereco_texto' - 'contato' - c_form_keys
                       - 'creditos' - 'tags' - 'codigo' - 'vinculosTitulo' - 'images' - 'coverFileId')
               || jsonb_set(c_extras, '{origem}', (c_extras->'origem')
                    || jsonb_build_object(
                         'titulo_md5', CASE WHEN v_old->'origem'->>'titulo_md5' IS NULL OR md5(v_old_titulo) = v_old->'origem'->>'titulo_md5'
                                            THEN c_extras->'origem'->>'titulo_md5' ELSE v_old->'origem'->>'titulo_md5' END,
                         'descricao_md5', CASE WHEN v_old->'origem'->>'descricao_md5' IS NULL OR md5(coalesce(v_old_desc, '')) = v_old->'origem'->>'descricao_md5'
                                               THEN c_extras->'origem'->>'descricao_md5' ELSE v_old->'origem'->>'descricao_md5' END))
               || jsonb_strip_nulls(jsonb_build_object('images', CASE WHEN jsonb_array_length(v_images) > 0 THEN v_images END, 'coverFileId', v_cover)),
      updated_at = now()
    WHERE id = v_sid;
    RAISE NOTICE 'lugares/%: atualizado (service id %)', c_slug, v_sid;
  END IF;

  -- Endereço (apaga os do anúncio e grava um, principal)
  DELETE FROM public.service_addresses WHERE service_id = v_sid;
  BEGIN
    SELECT lc.id::text INTO v_ibge FROM public.location_city lc JOIN public.location_state ls ON ls.id = lc.state_id
    WHERE lower(lc.name) = lower('Cuiabá') AND upper(ls.code) = 'MT' LIMIT 1;
  EXCEPTION WHEN undefined_table THEN v_ibge := NULL;
  END;
  IF v_ibge IS NULL THEN RAISE NOTICE 'lugares/%: cidade % / % sem código IBGE em location_city', c_slug, 'Cuiabá', 'MT'; END IF;
  INSERT INTO public.service_addresses
    (service_id, label, street, number, complement, neighborhood, city, state, city_ibge,
     latitude, longitude, is_primary, tenant_id, created_by, active)
  VALUES (v_sid, c_titulo, 'Avenida Jornalista Arquimedes Pereira Lima', NULL, NULL, NULL, 'Cuiabá', 'MT', v_ibge,
          -15.61332, -56.05044, true, v_tenant, v_root, true);

  -- Respostas do formulário (mesmas chaves de extras)
  IF v_form_id IS NOT NULL THEN
    INSERT INTO public.form_results
      (form_id, form_key, reference_id, domain, version, schema_snapshot, answers, submitted_by, tenant_id)
    VALUES (v_form_id, v_form, v_sid::text, 'service', v_form_ver, v_form_schema, c_answers, v_root, v_tenant)
    ON CONFLICT (tenant_id, domain, reference_id) DO UPDATE SET
      answers = EXCLUDED.answers, version = EXCLUDED.version, schema_snapshot = EXCLUDED.schema_snapshot,
      form_id = EXCLUDED.form_id, form_key = EXCLUDED.form_key, updated_at = now();
  END IF;

  -- Subcategorias
  DELETE FROM public.service_categories_sub scs USING public.categories_sub cs
  WHERE scs.service_id = v_sid AND cs.id = scs.category_sub_id
    AND (cs.category_id <> v_cat OR cs.slug <> ALL(c_subs));
  INSERT INTO public.service_categories_sub (service_id, category_group_id, category_id, category_sub_id, tenant_id, created_by)
  SELECT v_sid, v_group, v_cat, cs.id, v_tenant, v_root
  FROM public.categories_sub cs WHERE cs.category_id = v_cat AND cs.slug = ANY(c_subs)
  ON CONFLICT (service_id, category_sub_id) DO NOTHING;
END
